const VOICE={mode:'read',playing:false,pending:[],selected:'narrator'};
function pickVoice(who){const voices=window.speechSynthesis?.getVoices()||[];const rus=voices.filter(v=>/^ru([-_]|$)/i.test(v.lang));if(!rus.length)return null;const male=/ilya|viktor|narrator/.test(who),index=({narrator:0,marina:1,elena:3,ilya:2,viktor:4})[who]||0;const ranked=rus.slice().sort((a,b)=>(/natural|premium|online|neural/i.test(b.name)?1:0)-(/natural|premium|online|neural/i.test(a.name)?1:0));return ranked[index%ranked.length]||ranked[0]}
const VOICE_STYLE={narrator:{rate:.89,pitch:.87},marina:{rate:1.01,pitch:1.2},elena:{rate:.93,pitch:1.08},ilya:{rate:.98,pitch:.82},viktor:{rate:.83,pitch:.67}};
function stopVoice(){try{window.speechSynthesis?.cancel()}catch(e){}VOICE.playing=false;VOICE.pending=[];const t=document.getElementById('voiceState');if(t)t.textContent='Озвучка остановлена'}
function speakParts(parts){stopVoice();if(!('speechSynthesis' in window)){toast('В этом браузере нет речевого синтеза. Текст остаётся доступен.');return}VOICE.pending=parts.filter(p=>p.text&&p.text.trim());VOICE.playing=true;const label=document.getElementById('voiceState');if(label)label.textContent='ВОСПРОИЗВЕДЕНИЕ / МОЖНО ЧИТАТЬ ВМЕСТЕ С ГОЛОСОМ';function next(){if(!VOICE.playing||!VOICE.pending.length){VOICE.playing=false;const t=document.getElementById('voiceState');if(t)t.textContent='Озвучка завершена';return}const part=VOICE.pending.shift(),utterance=new SpeechSynthesisUtterance(part.text);utterance.lang='ru-RU';const v=pickVoice(part.who);if(v)utterance.voice=v;const style=VOICE_STYLE[part.who]||VOICE_STYLE.narrator;utterance.rate=style.rate;utterance.pitch=style.pitch;utterance.volume=.92;utterance.onend=next;utterance.onerror=()=>{if(VOICE.playing)next()};window.speechSynthesis.speak(utterance)}next()}
function voiceControls(){return `<div class="voice-controls" role="group" aria-label="Режим истории"><span>РЕЖИМ ИСТОРИИ</span><button class="${VOICE.mode==='read'?'selected':''}" data-action="voice-mode" data-id="read">▤ Читать</button><button class="${VOICE.mode==='listen'?'selected':''}" data-action="voice-mode" data-id="listen">◖ Слушать</button><button data-action="voice-stop">■ Стоп</button><small id="voiceState">Голоса зависят от устройства и браузера</small></div>`}
function noiseBurst(kind='paper'){if(!SFX.enabled)return;try{const A=window.AudioContext||window.webkitAudioContext;SFX.ctx=SFX.ctx||new A();const c=SFX.ctx;if(c.state==='suspended')c.resume();const now=c.currentTime;const durations={paper:.21,stamp:.28,clue:.35,step:.15,success:.68},dur=durations[kind]||.17;
const buffer=c.createBuffer(1,Math.floor(c.sampleRate*dur),c.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++){const t=i/samples.length;const n=Math.random()*2-1;samples[i]=n*(kind==='stamp'?Math.pow(1-t,8):kind==='paper'?(Math.sin(t*Math.PI)*.5+.1):Math.pow(1-t,2))*.7}
const src=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();src.buffer=buffer;filter.type=kind==='paper'?'highpass':'lowpass';filter.frequency.value=kind==='paper'?950:kind==='stamp'?490:kind==='clue'?850:1700;gain.gain.value=kind==='stamp'?.13:kind==='paper'?.065:.055;src.connect(filter).connect(gain).connect(c.destination);src.start(now);
if(kind==='clue'||kind==='success'){const osc=c.createOscillator(),og=c.createGain();osc.type='triangle';osc.frequency.setValueAtTime(kind==='success'?310:210,now);osc.frequency.exponentialRampToValueAtTime(kind==='success'?490:270,now+dur);og.gain.setValueAtTime(.0001,now);og.gain.exponentialRampToValueAtTime(.028,now+.02);og.gain.exponentialRampToValueAtTime(.0001,now+dur);osc.connect(og).connect(c.destination);osc.start(now);osc.stop(now+dur)}}catch(e){}}
const sound=(kind='paper')=>noiseBurst(kind);
let st;const initial=()=>({scene:'pass',found:[],flipped:[],visited:['pass'],solved:{safe:false,photo:false,witness:false,timeline:false,audit:false,optics:false,cross:false},dialogues:{},revelations:[],storySeen:false,timeline:[],completed:false,selected:null});
function load(){try{let r=JSON.parse(localStorage.getItem(LS));st=r&&Array.isArray(r.found)&&r.solved?{...initial(),...r,solved:{...initial().solved,...r.solved},dialogues:r.dialogues||{},revelations:r.revelations||[],storySeen:!!r.storySeen}:initial()}catch(e){st=initial()}}function save(){try{localStorage.setItem(LS,JSON.stringify(st))}catch(e){}}function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(t){let el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>el.classList.remove('show'),3200)}
let activeView='home',modalKind='',activeEvidenceId=null,drag=null,zoom=1,dx=0,dy=0;function resetCamera(){zoom=1;dx=dy=0;applyCamera()}function applyCamera(){const cam=$('sceneCamera');if(cam)cam.style.transform=`translate3d(${dx}px,${dy}px,0) scale(${zoom})`;}
function go(view){activeView=view;const home=view==='home';$('homeScreen').classList.toggle('hidden',!home);$('homeMore').classList.toggle('hidden',!home);$('gameScreen').classList.toggle('hidden',home);window.scrollTo({top:0,behavior:'instant'});if(!home){renderGame();if(!st.storySeen){st.storySeen=true;save();openStory();}}}
const sc=()=>scenes.find(s=>s.id===st.scene)||scenes[0];function add(id){if(!C[id])return;if(!st.found.includes(id)){st.found.push(id);save();renderGame();sound('clue');toast('Улика добавлена в досье · '+C[id].name)}openInspect(id)}
function progress(){if(st.completed)return 100;let n=Object.values(st.solved).filter(Boolean).length;return Math.min(97,Math.round((st.found.length/18*.62+n/7*.38)*100))}function completedScene(id){const ids=scenes.find(s=>s.id===id)?.spots.filter(x=>C[x[0]]).map(x=>x[0])||[];return ids.filter(k=>st.found.includes(k)).length+'/'+ids.length}
function renderGame(){const scene=sc();$('sceneImage').src='./assets/'+scene.image;$('sceneImage').alt=scene.name;$('sceneTitle').textContent=scene.name;$('currentTitle').textContent='Невеста Семи ветров';$('sceneCategory').textContent=scene.category;$('gameStage').textContent=scene.short.toUpperCase();$('sceneDescription').textContent=scene.desc;$('scenePrompt').textContent='Нажимай на точки, чтобы изучать следы';$('sceneCount').textContent=completedScene(scene.id);$('progressFill').style.width=progress()+'%';$('progressLabel').textContent=progress()+'%';$('locationList').innerHTML=scenes.map((x,i)=>`<button type="button" class="place-button ${x.id===scene.id?'active':''}" data-action="place" data-id="${x.id}"><img class="place-thumb" src="./assets/${x.image}" alt=""/><span><strong>${x.short}</strong><small>${completedScene(x.id)} · Место ${String(i+1).padStart(2,'0')}</small></span></button>`).join('');$('hotspotLayer').innerHTML=scene.spots.map(([key,x,y])=>{let isSafe=key==='safe',isWitness=key==='witness',id=C[key];let found=st.found.includes(key);let label=isSafe?'Закрытый сейф':isWitness?'Поговорить с Мариной':id?.name||key;return `<button type="button" class="hotspot ${found?'found':''}" data-action="${isSafe?'open-safe':isWitness?'open-person':'clue'}" data-id="${isWitness?'marina':key}" style="left:${x}%;top:${y}%" aria-label="${escape(label)}"><i>${found?'✓':isSafe?'▣':isWitness?'☷':'+'}</i><span class="tip">${escape(label)}</span></button>`}).join('')+([['archive','elena',65,56],['post','ilya',75,70],['road','viktor',36,44]].filter(x=>x[0]===scene.id).map(([,id,x,y])=>`<button type="button" class="hotspot hotspot-person" style="left:${x}%;top:${y}%" data-action="open-person" data-id="${id}" aria-label="Поговорить со свидетелем"><i>♧</i><span class="tip">Поговорить: ${escape(PEOPLE[id].name)}</span></button>`).join(''));$('evidenceCounter').textContent=String(st.found.length).padStart(2,'0')+'/18';$('evidencePreview').innerHTML=Array.from({length:9},(_,i)=>{const id=st.found[i];return id?`<button class="mini-evidence" data-action="inspect" data-id="${id}" title="${escape(C[id].name)}"><img src="./assets/${C[id].image}" alt="${escape(C[id].name)}"/></button>`:'<div class="mini-evidence"><span>?</span></div>'}).join('');const tasks=[['Осмотреть перевал',includes('fabric','photo')],['Проверить архив',includes('repair','route','journal')],['Найти источник света',includes('signal','lamp')],['Открыть сейф',st.solved.safe],['Проверить архивные документы',st.solved.audit],['Восстановить путь света',st.solved.optics],['Сравнить фотографии',st.solved.photo],['Проверить показания',st.solved.witness],['Восстановить хронологию',st.solved.timeline]];$('objectives').innerHTML=tasks.map(([name,done])=>`<div class="objective ${done?'done':''}"><b>${done?'✓':'·'}</b><span>${name}</span></div>`).join('');}
function includes(...keys){return keys.every(k=>st.found.includes(k))}function selectPlace(id){if(!scenes.find(s=>s.id===id))return;st.scene=id;if(!st.visited.includes(id))st.visited.push(id);save();resetCamera();closeModal();go('game');sound()}
function showModal(content,kind='general'){stopVoice();modalKind=kind;$('modalContent').innerHTML=content;$('modalRoot').classList.remove('hidden');document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal-close')?.focus(),60)}function closeModal(){stopVoice();modalKind='';$('modalRoot').classList.add('hidden');$('modalContent').innerHTML='';document.body.style.overflow='';}
const btn=(a,text,extra='')=>`<button type="button" class="small-action ${extra}" data-action="${a}">${text}</button>`;
function openInspect(id){const c=C[id];if(!c)return;activeEvidenceId=id;const flipped=st.flipped.includes(id);showModal(`<div class="modal-pad"><div class="modal-kicker">ЛИЧНОЕ ДЕЛО / НАЙДЕННЫЙ ПРЕДМЕТ</div><div class="evidence-detail-grid"><div class="evidence-art ${flipped?'flip':''}" id="evidenceArt"><div class="evidence-object"><div class="face front"><img src="./assets/${c.image}" alt="${escape(c.name)}"/></div><div class="face back">${escape(c.back)}</div></div></div><div class="inspect-info"><span>${escape(c.type)} / ${escape(scenes.find(s=>s.id===c.scene)?.short||'')}</span><h2>${escape(c.name)}</h2><p>${escape(c.summary)}</p><div class="inspect-note">${flipped?escape(c.detail):'Переверни предмет: важная деталь может находиться на обратной стороне.'}</div><div class="modal-control-row"><button type="button" class="small-action primary" data-action="flip" data-id="${id}">↻ ПЕРЕВЕРНУТЬ</button><button type="button" class="small-action" data-action="inspect-zoom">⊕ ПРИБЛИЗИТЬ</button>${btn('open-dossier','▤ ДОСЬЕ')}</div><p class="inspect-small">Можно нажать на изображение предмета, чтобы перевернуть его.</p></div></div></div>`,'inspect');}
function doFlip(id){if(modalKind!=='inspect')return;const el=$('evidenceArt');el.classList.toggle('flip');if(!st.flipped.includes(id)){st.flipped.push(id);save();setTimeout(()=>{toast('Найдена деталь на обороте предмета');openInspect(id)},530)}else{const note=$('.inspect-note');if(note)note.textContent=el.classList.contains('flip')?C[id].detail:'Переверни предмет: важная деталь может находиться на обратной стороне.'}sound('paper')}
function openGuide(){showModal(`<div class="modal-pad"><div class="modal-kicker">САМЫЙ ПРОСТОЙ ПУТЬ В РАССЛЕДОВАНИЕ</div><h2>Один клик — одна находка.</h2><p class="modal-lead">Никаких сложных комбинаций управления. Выбирай место на карте, нажимай на подсвеченные предметы и читай детали с обратной стороны. Каждая улика останется в досье, к ней можно вернуться в любой момент.</p><div class="modal-columns"><div class="paper"><small>ПАМЯТКА СЛЕДОВАТЕЛЯ</small><strong>01 / ИССЛЕДУЙ</strong><p>Найди на сцене светящиеся точки и нажми на них. Масштаб меняется кнопками + и −.</p><strong>02 / ПРОВЕРЯЙ</strong><p>Дневник, карта и медный жетон дают цифры сейфа. Другие находки помогут проверить версии.</p><strong>03 / РЕШИ</strong><p>Четыре задачи доступны через досье. Финальный вывод открывается после их прохождения.</p></div><img src="./assets/post.webp" style="width:100%;height:100%;object-fit:cover;min-height:300px" alt="Наблюдательный пост"/></div><div class="modal-control-row">${btn('play','ПЕРЕЙТИ К ИГРЕ ↗','primary')}</div></div>`)}
function openMap(){showModal(`<div class="map-dialog"><div class="map-head"><h2>Карта расследования</h2><span>НОВОРОССИЙСК · 05 МЕСТ · УСЛОВНАЯ СХЕМА</span></div><div class="map-surface"><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="map-route"><path d="M31 30 L68 32 L50 55 L28 73 L73 75" fill="none" stroke="#d2b58b" stroke-width=".55" stroke-dasharray="1.8 1.5" opacity=".7"/></svg>${scenes.map((s,i)=>`<button class="map-point" style="left:${s.map[0]}%;top:${s.map[1]}%" data-action="place" data-id="${s.id}"><i>${i+1}</i><span><strong>${s.short}</strong><small>${completedScene(s.id)} улик</small></span></button>`).join('')}<div class="map-note">Пять игровых локаций. Порядок свободный, а расследование сохраняется автоматически. География схематичная.</div></div></div>`,'map');}
function openDossier(){showModal(`<div class="modal-pad"><div class="modal-kicker">АРХИВ НАЙДЕННЫХ МАТЕРИАЛОВ · ${st.found.length} / 18</div><h2>Досье расследования</h2><p class="modal-lead">Собирай улики и возвращайся к их обратной стороне. На доске также доступны задачи, которые приводят к финальному выводу.</p><div class="modal-control-row">${btn('open-safe',st.solved.safe?'✓ СЕЙФ ОТКРЫТ':'▣ КОДОВЫЙ ЗАМОК')}${btn('open-photo',st.solved.photo?'✓ ФОТО СРАВНЕНЫ':'⌕ СРАВНЕНИЕ ФОТО')}${btn('open-people','♧ ПЕРСОНАЖИ И ДОПРОСЫ')}${btn('open-story','▤ ЖУРНАЛ ИСТОРИИ')}${btn('open-timeline',st.solved.timeline?'✓ ВРЕМЯ ВОССТАНОВЛЕНО':'◷ ХРОНОЛОГИЯ')}${btn('open-archive-logic',st.solved.audit?'✓ АРХИВ ПРОВЕРЕН':'▤ СВЕРКА ДОКУМЕНТОВ')}${btn('open-optics-logic',st.solved.optics?'✓ ПУТЬ СВЕТА ВОССТАНОВЛЕН':'⌖ ПУТЬ СВЕТА')}${btn('open-cross',st.solved.cross?'✓ ПЕРЕКРЁСТНАЯ ПРОВЕРКА':'⌁ ПЕРЕКРЁСТНАЯ ПРОВЕРКА')}${btn('open-verdict','✧ ФИНАЛ')}</div><div class="dossier-grid">${st.found.length?st.found.map(id=>`<button class="dossier-card" data-action="inspect" data-id="${id}"><img src="./assets/${C[id].image}" alt=""/><div><strong>${escape(C[id].name)}</strong><small>${escape(C[id].type)}</small><br/><span class="tag">ИЗУЧИТЬ ↗</span></div></button>`).join(''):'<p>Пока нет найденных улик. Начни с перевала.</p>'}</div><div class="modal-control-row">${btn('reset-confirm','↺ НАЧАТЬ ЗАНОВО')}</div></div>`,'dossier')}
function openSafe(){
const ready=includes('route','van','signal','harborlog','token');
showModal(`<div class="modal-pad logic-puzzle"><div class="modal-kicker">НАБЛЮДАТЕЛЬНЫЙ ПОСТ / ШИФР</div><h2>Три знака. Три источника.</h2><p class="modal-lead">На жетоне есть последовательность <b>дорога · часы · якорь</b>. Для каждого знака найди число, выведенное из материалов разных мест. Готовой комбинации нигде нет.</p><div class="logic-grid"><article><b>⌁ ДОРОГА</b><p>Какой номер маршрута ведёт к наблюдательному посту?</p></article><article><b>◷ ЧАСЫ</b><p>Сколько минут прошло от въезда автомобиля до включения света?</p></article><article><b>⚓ ПРИЧАЛ</b><p>С какого причала зарегистрировали луч раньше снимка?</p></article></div><div class="modal-columns"><div><div class="lock-wheels">${[0,1,2].map(i=>`<div class="wheel"><button data-action="wheel-up" data-id="${i}">▲</button><b id="digit${i}">${wheels[i]}</b><button data-action="wheel-down" data-id="${i}">▼</button></div>`).join('')}</div><div class="puzzle-result" id="puzzleResult">${st.solved.safe?'✓ Сейф открыт.':ready?'Источники собраны. Теперь проверь свои выводы.':'Нужны маршрут, отметки проезда и сигнала, журнал причала и жетон.'}</div><div class="modal-control-row">${btn('check-safe','ПРОВЕРИТЬ КОМБИНАЦИЮ','primary')}${btn('open-dossier','↩ ДОСЬЕ')}</div></div><div class="modal-cover"><img src="./assets/post.webp" alt="Наблюдательный пост"/></div></div></div>`,'safe')
}
const wheels=[0,0,0];function wheel(i,dir){wheels[i]=(wheels[i]+dir+10)%10;const el=$('digit'+i);if(el)el.textContent=wheels[i];sound()}function checkSafe(){
const el=$('puzzleResult');if(!includes('route','van','signal','harborlog','token')){el.textContent='Не хватает данных. Проверь документы в архиве, на дороге, посту и причале.';return}
const minutes=(21*60+9)-(21*60+4);
if(wheels.join('')==='3'+minutes+'7'){st.solved.safe=true;save();renderGame();el.textContent='✓ Замок открыт. Три независимых источника сошлись. Внутри журнал выдачи оборудования.';toast('Шифр разгадан')}
else el.textContent='Комбинация не совпала. Знаки на жетоне обозначают разные источники информации, а не готовые числа.';
}
let compareCount=0;function openPhoto(){showModal(`<div class="modal-pad"><div class="modal-kicker">АРХИВНОЕ СРАВНЕНИЕ / ГОЛОВОЛОМКА 02</div><h2>Один кадр. Два объяснения.</h2><p class="modal-lead">Сравни вечернюю фотографию с данными наблюдательного поста. Что вызвало светящийся силуэт?</p><div class="modal-columns"><div class="modal-cover" id="compareBox"><img src="./assets/pass.webp" id="comparisonImage" alt="Перевал Семь ветров"/><span class="modal-cover-label" id="comparisonLabel">КАДР / 21:12</span></div><div><div class="paper"><small>СЛУЖЕБНАЯ ЗАМЕТКА</small><strong>Проверка оптического следа</strong><p>На одном изображении силуэт кажется самостоятельным источником света. На другом видно направление луча от поста.</p><p>Установи связь между световым прибором и тканью.</p></div><div class="modal-control-row">${btn('toggle-photo','⇄ СРАВНИТЬ КАДРЫ','primary')}${btn('open-dossier','↩ ДОСЬЕ')}</div><div class="choice-grid"><button class="choice" data-action="photo-answer" data-id="reflection"><i>○</i><span>Отражение направленного света на технической ткани</span></button><button class="choice" data-action="photo-answer" data-id="person"><i>○</i><span>Человек с фонарём на дороге</span></button><button class="choice" data-action="photo-answer" data-id="unknown"><i>○</i><span>Причину невозможно установить</span></button></div><div class="puzzle-result" id="puzzleResult">${st.solved.photo?'✓ Источник света установлен.':'Для проверки пригодятся фото с перевала, радиозапись и ткань.'}</div></div></div></div>`,'photo');compareCount=0}
function photoAnswer(id){const el=$('puzzleResult');if(id==='reflection'&&includes('photo','signal','fabric')){st.solved.photo=true;save();renderGame();el.textContent='✓ Верно: прожектор осветил светоотражающий лоскут, и ветер придал ему форму фигуры.';toast('Оптическая загадка раскрыта')}else if(!includes('photo','signal','fabric'))el.textContent='Недостаточно данных. Найди фото, ленту радиосигнала и ткань.';else el.textContent='Версия не подтверждается уликами. Сопоставь время снимка и включения света.'}
